package com.citacloud.springboot.contacloud.app.services;

import com.citacloud.springboot.contacloud.app.dto.*;
import com.citacloud.springboot.contacloud.app.models.*;
import com.citacloud.springboot.contacloud.app.repositories.*;
import com.citacloud.springboot.contacloud.app.security.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;

@Service
public class DescuentoVentaService {
    private static final int SCALE=4;
    private final ConfiguracionDescuentoVentaRepository configuraciones;private final ConfiguracionDescuentoService configuracionService;
    private final LimiteDescuentoRolRepository limites;private final MotivoDescuentoVentaRepository motivos;private final ProductRepository productos;
    private final UsuarioEmpresaRepository accesos;private final AutorizacionDescuentoVentaRepository autorizaciones;
    private final MonedaRepository monedas;private final PasswordEncoder passwordEncoder;private final AuditoriaService auditoria;
    public DescuentoVentaService(ConfiguracionDescuentoVentaRepository configuraciones,ConfiguracionDescuentoService configuracionService,
            LimiteDescuentoRolRepository limites,MotivoDescuentoVentaRepository motivos,ProductRepository productos,
            UsuarioEmpresaRepository accesos,AutorizacionDescuentoVentaRepository autorizaciones,MonedaRepository monedas,
            PasswordEncoder passwordEncoder,AuditoriaService auditoria){this.configuraciones=configuraciones;this.configuracionService=configuracionService;this.limites=limites;this.motivos=motivos;this.productos=productos;this.accesos=accesos;this.autorizaciones=autorizaciones;this.monedas=monedas;this.passwordEncoder=passwordEncoder;this.auditoria=auditoria;}

    @Transactional
    @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('facturas.descuentos.aplicar')")
    public OpcionesDescuentoPosDto opciones(){var p=TenantContext.principalActual();UUID empresa=EmpresaContext.requerirEmpresaId();ConfiguracionDescuentoVenta c=configuracionService.asegurar(p.tenantId(),empresa,p.usuarioId());if(!c.isEnabled())throw new ReglaNegocioException("Los descuentos están deshabilitados para esta empresa.");String moneda=monedas.findByEmpresaIdAndMonedaBaseTrue(empresa).map(Moneda::getCodigoIso).orElse("—");List<ConfiguracionDescuentoDto.Motivo> ms=motivos.findAllByTenantIdAndEmpresaIdAndActivoTrueOrderByNombre(p.tenantId(),empresa).stream().map(x->new ConfiguracionDescuentoDto.Motivo(x.getId(),x.getNombre(),x.isOtro(),true,x.getVersion())).toList();return new OpcionesDescuentoPosDto(c.isPermiteVenta(),c.isPermiteLinea(),c.isPermitePorcentaje(),c.isPermiteMonto(),c.isRequiereMotivo(),c.isPermiteAutorizacion(),moneda,ms);}

    @Transactional
    @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('facturas.descuentos.aplicar')")
    public VistaPreviaDescuentoDto previsualizar(SolicitudVistaPreviaDescuentoInput input){return calcular(input,true).vista();}

    @Transactional
    @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('facturas.descuentos.solicitar_autorizacion')")
    public AutorizacionDescuentoDto autorizar(AutorizarDescuentoInput input){if(input==null||input.solicitud()==null)throw new ReglaNegocioException("La solicitud de autorización es obligatoria.");String usuario=input.usuario()==null?"":input.usuario().trim();if(usuario.isEmpty()||input.clave()==null||input.clave().isEmpty())throw new ReglaNegocioException("Indica el usuario y la contraseña del autorizador.");CalculoValidado calculo=calcular(input.solicitud(),true);if(!calculo.vista().requiereAutorizacion())throw new ReglaNegocioException("Este descuento no requiere autorización superior.");var p=TenantContext.principalActual();UUID empresa=EmpresaContext.requerirEmpresaId();UsuarioEmpresa acceso=accesos.findForAuthentication(empresa,usuario).filter(x->p.tenantId().equals(x.getUsuario().getTenantId())).orElseThrow(()->new ReglaNegocioException("Las credenciales del autorizador no son válidas."));if(!passwordEncoder.matches(input.clave(),acceso.getUsuario().getPasswordHash()))throw new ReglaNegocioException("Las credenciales del autorizador no son válidas.");if(acceso.getRol().getPermisos().stream().noneMatch(x->"facturas.descuentos.autorizar".equals(x.getCodigo())))throw new ReglaNegocioException("El usuario no tiene permiso para autorizar descuentos.");Limite limiteAutorizador=limite(p.tenantId(),empresa,acceso.getRol().getId());if(excede(calculo.vista().porcentajeEfectivo(),calculo.vista().montoDescuento(),limiteAutorizador))throw new ReglaNegocioException("El límite del autorizador no permite aprobar este descuento.");AutorizacionDescuentoVenta a=new AutorizacionDescuentoVenta(p.tenantId(),empresa,input.solicitud().operacionId(),p.usuarioId(),acceso.getUsuario().getId(),calculo.rolSolicitanteId(),acceso.getRol().getId(),calculo.descuento().alcance(),calculo.descuento().tipo(),null,calculo.descuento().valor(),calculo.vista().baseElegible(),calculo.vista().montoDescuento(),calculo.limiteSolicitante().porcentaje(),calculo.limiteSolicitante().monto(),limiteAutorizador.porcentaje(),limiteAutorizador.monto(),calculo.motivo()==null?null:calculo.motivo().getId(),calculo.motivo()==null?null:calculo.motivo().getNombre(),detalle(calculo.descuento().detalle()),calculo.fingerprint());a=autorizaciones.saveAndFlush(a);auditoria.registrar("SALES_DISCOUNT_AUTHORIZED","AutorizacionDescuentoVenta",a.getId(),"{\"solicitante\":\""+p.usuarioId()+"\",\"autorizador\":\""+acceso.getUsuario().getId()+"\",\"monto\":"+calculo.vista().montoDescuento()+",\"lineas\":"+calculo.descuento().lineaIds().size()+"}");return new AutorizacionDescuentoDto(a.getId(),acceso.getUsuario().getUsuario());}

    @Transactional
    public ValidacionConfirmacion validarConfirmacion(UUID operacionId,DescuentoVentaInput descuento,List<LineaVistaPreviaDescuentoInput> lineas){if(descuento==null)return ValidacionConfirmacion.sinDescuento(lineas);var p=TenantContext.principalActual();if(!p.permisos().contains("facturas.descuentos.aplicar"))throw new ReglaNegocioException("No tienes permiso para aplicar descuentos.");CalculoValidado c=calcular(new SolicitudVistaPreviaDescuentoInput(operacionId,descuento,lineas),false);AutorizacionDescuentoVenta autorizacion=null;if(c.vista().requiereAutorizacion()){if(descuento.autorizacionId()==null)throw new ReglaNegocioException("El descuento requiere autorización.");autorizacion=autorizaciones.bloquear(descuento.autorizacionId(),p.tenantId(),p.empresaId()).orElseThrow(()->new ReglaNegocioException("La autorización del descuento no es válida."));if(autorizacion.getStatus()!=EstadoAutorizacionDescuento.AUTHORIZED||!operacionId.equals(autorizacion.getOperacionId())||!p.usuarioId().equals(autorizacion.getSolicitadaPor())||!c.fingerprint().equals(autorizacion.getFingerprint()))throw new ReglaNegocioException("La autorización no corresponde al descuento actual. Solicita una nueva autorización.");}
        return new ValidacionConfirmacion(c.vista(),c.motivo(),autorizacion==null?null:autorizacion.getId(),autorizacion==null?null:autorizacion.getAutorizadaPor(),autorizacion==null?null:autorizacion.getAutorizadaEn(),c.descuento());}

    @Transactional
    public void consumirAutorizacion(UUID autorizacionId,UUID facturaId){if(autorizacionId==null)return;var p=TenantContext.principalActual();AutorizacionDescuentoVenta a=autorizaciones.bloquear(autorizacionId,p.tenantId(),p.empresaId()).orElseThrow(()->new ReglaNegocioException("La autorización del descuento no es válida."));a.consumir(facturaId);autorizaciones.save(a);}

    private CalculoValidado calcular(SolicitudVistaPreviaDescuentoInput input,boolean validarSolicitud){if(input==null||input.operacionId()==null||input.descuento()==null)throw new ReglaNegocioException("Los datos del descuento son obligatorios.");var p=TenantContext.principalActual();UUID empresa=EmpresaContext.requerirEmpresaId();ConfiguracionDescuentoVenta config=configuraciones.findByTenantIdAndEmpresaId(p.tenantId(),empresa).orElseGet(()->configuracionService.asegurar(p.tenantId(),empresa,p.usuarioId()));DescuentoVentaInput d=input.descuento();if(!config.isEnabled())throw new ReglaNegocioException("Los descuentos están deshabilitados para esta empresa.");if(d.alcance()==AlcanceDescuentoVenta.SALE&&!config.isPermiteVenta())throw new ReglaNegocioException("El descuento general no está habilitado.");if(d.alcance()==AlcanceDescuentoVenta.LINE&&!config.isPermiteLinea())throw new ReglaNegocioException("El descuento por producto no está habilitado.");if(d.tipo()==TipoDescuentoVenta.PERCENTAGE&&!config.isPermitePorcentaje())throw new ReglaNegocioException("El descuento porcentual no está habilitado.");if(d.tipo()==TipoDescuentoVenta.AMOUNT&&!config.isPermiteMonto())throw new ReglaNegocioException("El descuento por monto no está habilitado.");MotivoDescuentoVenta motivo=null;if(d.motivoId()!=null)motivo=motivos.findByIdAndTenantIdAndEmpresaId(d.motivoId(),p.tenantId(),empresa).filter(MotivoDescuentoVenta::isActivo).orElseThrow(()->new ReglaNegocioException("El motivo seleccionado no está disponible."));if(config.isRequiereMotivo()&&motivo==null)throw new ReglaNegocioException("Selecciona el motivo del descuento.");if(motivo!=null&&motivo.isOtro()&&(d.detalle()==null||d.detalle().trim().isEmpty()))throw new ReglaNegocioException("Indica el detalle del motivo Otro.");List<DescuentoVentaCalculo.Linea> calculables=new ArrayList<>();Set<UUID> ids=new HashSet<>();if(input.lineas()==null||input.lineas().isEmpty())throw new ReglaNegocioException("Agregue al menos un producto antes de aplicar un descuento.");for(LineaVistaPreviaDescuentoInput l:input.lineas()){if(l==null||l.lineaId()==null||l.productoId()==null||!ids.add(l.lineaId())||l.cantidad()==null||l.cantidad().signum()<=0)throw new ReglaNegocioException("Las líneas de la venta no son válidas.");Producto producto=productos.findByIdAndTenantIdAndEmpresaId(l.productoId(),p.tenantId(),empresa).filter(Producto::isActivo).orElseThrow(()->new RecursoNoEncontradoException("Producto no encontrado."));BigDecimal precio=escala(producto.getPrecioVenta());BigDecimal esperado=escala(l.precioEsperado());BigDecimal tasa=producto.getImpuestoVenta()!=null&&producto.getImpuestoVenta().isActivo()?producto.getImpuestoVenta().getPorcentaje():BigDecimal.ZERO;if(precio.compareTo(esperado)!=0||tasa.setScale(6,RoundingMode.HALF_UP).compareTo((l.tasaImpuestoEsperada()==null?BigDecimal.ZERO:l.tasaImpuestoEsperada()).setScale(6,RoundingMode.HALF_UP))!=0)throw new ReglaNegocioException("El precio o impuesto de "+producto.getNombre()+" cambió. Actualiza la venta.");BigDecimal bruto=precio.multiply(l.cantidad().setScale(SCALE,RoundingMode.HALF_UP)).setScale(SCALE,RoundingMode.HALF_UP);calculables.add(new DescuentoVentaCalculo.Linea(l.lineaId(),producto.getId(),bruto,tasa,producto.isPermiteDescuentos()));}
        DescuentoVentaCalculo.Resultado r=DescuentoVentaCalculo.calcular(d.alcance(),d.tipo(),d.valor(),d.lineaIds(),calculables);UsuarioEmpresa acceso=accesoActual(p,empresa);Limite limite=limite(p.tenantId(),empresa,acceso.getRol().getId());boolean requiere=excede(r.porcentajeEfectivo(),r.montoDescuento(),limite);if(requiere&&!config.isPermiteAutorizacion())throw new ReglaNegocioException("El descuento supera el límite permitido y la autorización superior está deshabilitada.");if(requiere&&validarSolicitud&&!p.permisos().contains("facturas.descuentos.solicitar_autorizacion"))throw new ReglaNegocioException("El descuento supera tu límite y no tienes permiso para solicitar autorización.");List<VistaPreviaDescuentoDto.Asignacion> asignaciones=r.asignaciones().stream().map(x->new VistaPreviaDescuentoDto.Asignacion(x.lineaId(),x.productoId(),x.subtotalBruto(),x.descuento(),x.baseImponible(),x.impuesto(),x.total())).toList();VistaPreviaDescuentoDto vista=new VistaPreviaDescuentoDto(r.baseElegible(),r.montoDescuento(),r.importePosterior(),r.porcentajeEfectivo(),requiere,limite.porcentaje(),limite.monto(),motivo==null?null:motivo.getNombre(),motivo!=null&&motivo.isOtro(),asignaciones);String huella=fingerprint(input.operacionId(),d,vista,motivo);return new CalculoValidado(vista,d,motivo,limite,acceso.getRol().getId(),huella);}

    private UsuarioEmpresa accesoActual(com.citacloud.springboot.contacloud.app.security.TenantPrincipal p,UUID empresa){if(p.usuarioEmpresaId()!=null)return accesos.findByIdAndEmpresaId(p.usuarioEmpresaId(),empresa).orElseThrow(()->new ReglaNegocioException("No fue posible determinar el rol del usuario."));return accesos.findByUsuarioIdAndEmpresaId(p.usuarioId(),empresa).orElseThrow(()->new ReglaNegocioException("No fue posible determinar el rol del usuario."));}
    private Limite limite(UUID tenant,UUID empresa,UUID rol){return limites.findByTenantIdAndEmpresaIdAndRolIdAndActiveTrue(tenant,empresa,rol).map(x->new Limite(true,x.getPorcentajeMaximo(),x.getMontoMaximo())).orElse(new Limite(false,BigDecimal.ZERO.setScale(SCALE),BigDecimal.ZERO.setScale(SCALE)));}
    private static boolean excede(BigDecimal porcentaje,BigDecimal monto,Limite limite){if(!limite.configurado())return porcentaje.signum()>0||monto.signum()>0;return limite.porcentaje()!=null&&porcentaje.compareTo(limite.porcentaje())>0||limite.monto()!=null&&monto.compareTo(limite.monto())>0;}
    private static BigDecimal escala(BigDecimal v){return (v==null?BigDecimal.ZERO:v).setScale(SCALE,RoundingMode.HALF_UP);}
    private static String detalle(String v){if(v==null||v.isBlank())return null;String x=v.trim();if(x.length()>500)throw new ReglaNegocioException("El detalle del motivo excede 500 caracteres.");return x;}
    private static String fingerprint(UUID operacion,DescuentoVentaInput d,VistaPreviaDescuentoDto v,MotivoDescuentoVenta motivo){String asignaciones=v.asignaciones().stream().sorted(Comparator.comparing(x->x.lineaId().toString())).map(x->x.lineaId()+":"+x.productoId()+":"+x.descuento().toPlainString()).reduce("",(a,b)->a+"|"+b);String seleccion=d.lineaIds().stream().sorted().map(UUID::toString).reduce("",(a,b)->a+"|"+b);String raw=operacion+"|"+d.alcance()+"|"+d.tipo()+"|"+seleccion+"|"+d.valor().stripTrailingZeros().toPlainString()+"|"+(motivo==null?null:motivo.getId())+"|"+detalle(d.detalle())+"|"+v.baseElegible()+"|"+v.montoDescuento()+asignaciones;try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException ex){throw new IllegalStateException(ex);}}
    private record Limite(boolean configurado,BigDecimal porcentaje,BigDecimal monto){}
    private record CalculoValidado(VistaPreviaDescuentoDto vista,DescuentoVentaInput descuento,MotivoDescuentoVenta motivo,Limite limiteSolicitante,UUID rolSolicitanteId,String fingerprint){}
    public record ValidacionConfirmacion(VistaPreviaDescuentoDto vista,MotivoDescuentoVenta motivo,UUID autorizacionId,UUID autorizadaPor,java.time.OffsetDateTime autorizadaEn,DescuentoVentaInput descuento){static ValidacionConfirmacion sinDescuento(List<LineaVistaPreviaDescuentoInput> lineas){List<VistaPreviaDescuentoDto.Asignacion> asignaciones=(lineas==null?List.<LineaVistaPreviaDescuentoInput>of():lineas).stream().map(x->{BigDecimal bruto=escala(x.precioEsperado()).multiply(escala(x.cantidad())).setScale(SCALE,RoundingMode.HALF_UP);BigDecimal impuesto=bruto.multiply(x.tasaImpuestoEsperada()==null?BigDecimal.ZERO:x.tasaImpuestoEsperada()).divide(new BigDecimal("100"),SCALE,RoundingMode.HALF_UP);return new VistaPreviaDescuentoDto.Asignacion(x.lineaId(),x.productoId(),bruto,BigDecimal.ZERO.setScale(SCALE),bruto,impuesto,bruto.add(impuesto));}).toList();return new ValidacionConfirmacion(new VistaPreviaDescuentoDto(BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,false,null,null,null,false,asignaciones),null,null,null,null,null);}}
}
